#import "ABMCShortcutListController.h"
#import "ABMCUIHelpers.h"
#import <sqlite3.h>
#define Domain CFSTR("com.huynguyen.actionbuttonmulticlick")
#define Changed CFSTR("com.huynguyen.actionbuttonmulticlick/prefsChanged")
static BOOL ValidID(NSString*v){return[v isKindOfClass:NSString.class]&&[[NSUUID alloc]initWithUUIDString:v]!=nil;}

@interface ABMCShortcutListController () <UISearchBarDelegate>
@end
@implementation ABMCShortcutListController { NSString *_key,*_query;NSArray *_shortcuts;NSMutableOrderedSet *_chosen; }
- (instancetype)initWithPreferenceKey:(NSString*)key{if((self=[super initWithStyle:UITableViewStyleInsetGrouped])){_key=[key copy];self.title=@"指令列表";_chosen=[NSMutableOrderedSet orderedSet];}return self;}
- (void)viewDidLoad{[super viewDidLoad];_query=@"";self.tableView.rowHeight=64;UIView*h=[[UIView alloc]initWithFrame:CGRectMake(0,0,UIScreen.mainScreen.bounds.size.width,72)];UISearchBar*s=[[UISearchBar alloc]initWithFrame:CGRectInset(h.bounds,10,8)];s.placeholder=@"搜索全部快捷指令";s.delegate=self;[h addSubview:s];self.tableView.tableHeaderView=h;[self reloadShortcuts];}
- (void)viewWillAppear:(BOOL)animated {[super viewWillAppear:animated];[self loadSelection];}
- (NSArray*)paths{return @[@"/private/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/private/var/mobile/Library/Shortcuts/Shortcuts.db",@"/var/mobile/Library/Shortcuts/Shortcuts.db"];}
- (void)read:(NSString*)path into:(NSMutableDictionary*)results{sqlite3*db=NULL;if(sqlite3_open_v2(path.fileSystemRepresentation,&db,SQLITE_OPEN_READONLY|SQLITE_OPEN_NOMUTEX,NULL)!=SQLITE_OK){if(db)sqlite3_close(db);return;}sqlite3_stmt*s=NULL;const char*q="SELECT x.ZNAME,x.ZWORKFLOWID,COALESCE(i.ZGLYPHNUMBER,0),COALESCE(i.ZBACKGROUNDCOLORVALUE,0) FROM ZSHORTCUT x LEFT JOIN ZSHORTCUTICON i ON i.Z_PK=x.ZICON WHERE x.ZNAME IS NOT NULL AND x.ZWORKFLOWID IS NOT NULL AND COALESCE(x.ZTOMBSTONED,0)=0";if(sqlite3_prepare_v2(db,q,-1,&s,NULL)==SQLITE_OK)while(sqlite3_step(s)==SQLITE_ROW){const char*n=(const char*)sqlite3_column_text(s,0),*i=(const char*)sqlite3_column_text(s,1);if(!n||!i)continue;NSString*name=[[NSString stringWithUTF8String:n]stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet],*identifier=[[NSString stringWithUTF8String:i]uppercaseString];if(name.length&&ValidID(identifier))results[identifier]=@{ @"name":name,@"identifier":identifier,@"glyph":@(sqlite3_column_int64(s,2)),@"color":@(sqlite3_column_int64(s,3)) };}if(s)sqlite3_finalize(s);sqlite3_close(db);}
- (void)reloadShortcuts{NSMutableDictionary*r=[NSMutableDictionary dictionary];for(NSString*p in self.paths)[self read:p into:r];_shortcuts=[[r allValues]sortedArrayUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return[a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];}];[self loadSelection];}
- (NSArray*)visible{return!_query.length?(_shortcuts?:@[]):[_shortcuts filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary*i,NSDictionary*b){return[i[@"name"] localizedCaseInsensitiveContainsString:self->_query];}]];}
- (BOOL)isChosen:(NSDictionary *)candidate { NSString *identifier=candidate[@"identifier"]; for(NSDictionary *item in _chosen) if([item[@"identifier"] isEqualToString:identifier]) return YES; return NO; }
- (void)removeChosen:(NSDictionary *)candidate { NSString *identifier=candidate[@"identifier"]; for(NSInteger i=_chosen.count-1;i>=0;i--) if([_chosen[i][@"identifier"] isEqualToString:identifier]) [_chosen removeObjectAtIndex:i]; }
- (void)loadSelection { [_chosen removeAllObjects];CFStringRef raw=(CFStringRef)CFPreferencesCopyAppValue((__bridge CFStringRef)_key,Domain);NSString *action=raw?(__bridge_transfer NSString*)raw:nil;if([action hasPrefix:@"shortcutpanel:"]){CFPropertyListRef p=CFPreferencesCopyAppValue(CFSTR("shortcutPanels"),Domain);NSArray *items=p&&CFGetTypeID(p)==CFDictionaryGetTypeID()?[(__bridge NSDictionary*)p objectForKey:[action substringFromIndex:14]]:nil;if(p)CFRelease(p);for(NSDictionary *item in items)if([item isKindOfClass:NSDictionary.class])[_chosen addObject:item];}else if([action hasPrefix:@"shortcutid:"]){NSArray *v=[[action substringFromIndex:11] componentsSeparatedByString:@"|"];if(v.count>3)[_chosen addObject:@{ @"identifier":v[0],@"name":v[1],@"glyph":@([v[2] integerValue]),@"color":@([v[3] longLongValue]) }];} [self.tableView reloadData];}
- (void)saveSelection {if(!_chosen.count){CFStringRef oldRaw=(CFStringRef)CFPreferencesCopyAppValue((__bridge CFStringRef)_key,Domain);NSString *oldAction=oldRaw?(__bridge_transfer NSString*)oldRaw:nil;if([oldAction hasPrefix:@"shortcutpanel:"]){CFPropertyListRef oldPanels=CFPreferencesCopyAppValue(CFSTR("shortcutPanels"),Domain);NSMutableDictionary *clean=oldPanels&&CFGetTypeID(oldPanels)==CFDictionaryGetTypeID()?[(__bridge NSDictionary*)oldPanels mutableCopy]:[NSMutableDictionary dictionary];if(oldPanels)CFRelease(oldPanels);[clean removeObjectForKey:[oldAction substringFromIndex:14]];CFPreferencesSetAppValue(CFSTR("shortcutPanels"),(__bridge CFPropertyListRef)clean,Domain);}CFPreferencesSetAppValue((__bridge CFStringRef)_key,CFSTR("none"),Domain);CFPreferencesAppSynchronize(Domain);CFNotificationCenterPostNotification(CFNotificationCenterGetDarwinNotifyCenter(),Changed,NULL,NULL,YES);return;}CFStringRef oldRaw=(CFStringRef)CFPreferencesCopyAppValue((__bridge CFStringRef)_key,Domain);NSString *oldAction=oldRaw?(__bridge_transfer NSString*)oldRaw:nil;NSMutableArray*items=[NSMutableArray array];for(NSDictionary*i in _chosen.array){NSMutableDictionary*x=[i mutableCopy];UIImage*icon=ABMCWorkflowIconImage([i[@"glyph"]integerValue],[i[@"color"]longLongValue]);NSData*data=icon?UIImagePNGRepresentation(icon):nil;if(data)x[@"iconData"]=data;[items addObject:x];}NSString *action=nil;if(items.count==1){NSDictionary*i=items.firstObject;action=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",i[@"identifier"],i[@"name"],i[@"glyph"],i[@"color"]];}else{NSString*panelID=NSUUID.UUID.UUIDString;CFPropertyListRef v=CFPreferencesCopyAppValue(CFSTR("shortcutPanels"),Domain);NSMutableDictionary*panels=v&&CFGetTypeID(v)==CFDictionaryGetTypeID()?[(__bridge NSDictionary*)v mutableCopy]:[NSMutableDictionary dictionary];if(v)CFRelease(v);panels[panelID]=items;CFPreferencesSetAppValue(CFSTR("shortcutPanels"),(__bridge CFPropertyListRef)panels,Domain);action=[@"shortcutpanel:" stringByAppendingString:panelID];}if([oldAction hasPrefix:@"shortcutpanel:"]){ NSString *oldID=[oldAction substringFromIndex:14]; if(![oldID isEqualToString:[action substringFromIndex:14]]) { CFPropertyListRef oldPanels=CFPreferencesCopyAppValue(CFSTR("shortcutPanels"),Domain); NSMutableDictionary *clean=oldPanels&&CFGetTypeID(oldPanels)==CFDictionaryGetTypeID()?[(__bridge NSDictionary*)oldPanels mutableCopy]:[NSMutableDictionary dictionary];if(oldPanels)CFRelease(oldPanels);[clean removeObjectForKey:oldID];CFPreferencesSetAppValue(CFSTR("shortcutPanels"),(__bridge CFPropertyListRef)clean,Domain); } } CFPreferencesSetAppValue((__bridge CFStringRef)_key,(__bridge CFPropertyListRef)action,Domain);CFPreferencesAppSynchronize(Domain);CFNotificationCenterPostNotification(CFNotificationCenterGetDarwinNotifyCenter(),Changed,NULL,NULL,YES);}
- (NSInteger)tableView:(UITableView*)t numberOfRowsInSection:(NSInteger)s{return self.visible.count?:1;}
- (UITableViewCell*)tableView:(UITableView*)t cellForRowAtIndexPath:(NSIndexPath*)p{UITableViewCell*c=[t dequeueReusableCellWithIdentifier:@"ShortcutCell"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"ShortcutCell"];NSArray*items=self.visible;if(!items.count){ABMCApplyLargeIcon(c,ABMCTintedIcon(@"exclamationmark.circle",UIColor.secondaryLabelColor));c.textLabel.text=@"未读取到快捷指令";c.detailTextLabel.text=@"请打开一次快捷指令 App 后刷新";c.selectionStyle=UITableViewCellSelectionStyleNone;c.accessoryType=UITableViewCellAccessoryNone;return c;}NSDictionary*i=items[p.row];NSString*showKey=[@"shortcut." stringByAppendingString:i[@"identifier"]],*showIcon=ABMCDisplayIconToken(showKey,@"");ABMCApplyLargeIcon(c,ABMCTintedIcon(showIcon,nil)?:ABMCIconImageForBundleID(showIcon)?:ABMCWorkflowIconImage([i[@"glyph"]integerValue],[i[@"color"]longLongValue])?:ABMCTintedIcon(@"square.stack.3d.up.fill",nil));c.textLabel.font=[UIFont systemFontOfSize:18];c.textLabel.text=ABMCDisplayTitle(showKey,i[@"name"]);c.detailTextLabel.text=nil;c.selectionStyle=UITableViewCellSelectionStyleDefault;c.accessoryType=[self isChosen:i]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;return c;}
- (void)tableView:(UITableView*)t didSelectRowAtIndexPath:(NSIndexPath*)p{NSDictionary*i=self.visible[p.row];if([self isChosen:i])[self removeChosen:i];else if(_chosen.count<8)[_chosen addObject:i];else{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"最多 8 项" message:@"快捷指令面板最多展示 8 项。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];return;}[self saveSelection];[t reloadRowsAtIndexPaths:@[p] withRowAnimation:UITableViewRowAnimationNone];}
- (UISwipeActionsConfiguration *)tableView:(UITableView*)t trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath*)p{if(!self.visible.count)return nil;NSDictionary*i=self.visible[p.row];NSString*key=[@"shortcut." stringByAppendingString:i[@"identifier"]];UIContextualAction*edit=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleNormal title:@"修改" handler:^(__unused UIContextualAction*a,__unused UIView*v,void(^done)(BOOL)){ABMCShowPresentationEditor(self,key,i[@"name"],@"square.stack.3d.up.fill",^{[self.tableView reloadData];done(YES);});}];edit.backgroundColor=UIColor.systemBlueColor;UIContextualAction*clear=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:@"清空" handler:^(__unused UIContextualAction*a,__unused UIView*v,void(^done)(BOOL)){ABMCClearPresentationOverride(key);[self.tableView reloadData];done(YES);}];clear.backgroundColor=UIColor.systemGrayColor;return[UISwipeActionsConfiguration configurationWithActions:@[clear,edit]];}
- (void)searchBar:(UISearchBar*)s textDidChange:(NSString*)text{_query=[text copy]?:@"";[UIView performWithoutAnimation:^{[self.tableView reloadData];}];}
@end
